import{_ as a,C as s,c as l,o as f,ag as n,j as t,G as i,a as r}from"./chunks/framework.Bw-5EFTY.js";const w=JSON.parse('{"title":"FluentForms Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/fluentforms-integration-with-fluentaffiliate.md","filePath":"guide/integrations/fluentforms-integration-with-fluentaffiliate.md","lastUpdated":1755775918000}'),u={name:"guide/integrations/fluentforms-integration-with-fluentaffiliate.md"};function g(m,e,p,d,h,c){const o=s("ZoomableImage");return f(),l("div",null,[e[0]||(e[0]=n('<h1 id="fluentforms-integration-with-fluentaffiliate" tabindex="-1">FluentForms Integration with FluentAffiliate <a class="header-anchor" href="#fluentforms-integration-with-fluentaffiliate" aria-label="Permalink to &quot;FluentForms Integration with FluentAffiliate&quot;">​</a></h1><p>FluentForms is a powerful, lightweight, and user-friendly form builder for WordPress. When you connect it with FluentAffiliate, you can unlock two powerful capabilities: tracking affiliate commissions on your paid form submissions and creating custom affiliate registration forms.</p><p>This guide will show you how to set up both, starting with the simple way to track commissions.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Make sure both plugin FluentForms and FluentAffiliate are installed and activated on your website.</p></div><h2 id="enable-fluentforms-in-fluentaffiliate" tabindex="-1">Enable FluentForms in FluentAffiliate <a class="header-anchor" href="#enable-fluentforms-in-fluentaffiliate" aria-label="Permalink to &quot;Enable FluentForms in FluentAffiliate&quot;">​</a></h2><p>First, you need to activate the integration module in FluentAffiliate.</p><ol><li>Go to the <strong>FluentAffiliate Dashboard</strong>.</li><li>From the top menu, click on <strong>Settings</strong>, and from the left sidebar, select the <strong>Integration Settings</strong> option.</li><li>You will see a list of available integrations. Look for <strong>FluentForms</strong> in this list. To enable the integration, click on the <strong>toggle</strong> button next to FluentForms.</li></ol><p>Your <strong>FluentForms</strong> integration with <strong>FluentAffiliate</strong> is now active, allowing you to create affiliate registration forms and track form submissions.</p><p>In the <strong>Manage</strong> section, you&#39;ll find additional settings to customize how the integration works.</p>',9)),t("p",null,[i(o,{src:"/guide/public/images/integrations/fluentforms/fluentforms-integration-setup.webp",alt:"Integration Settings"})]),e[1]||(e[1]=n('<h2 id="set-custom-commission-rates-for-your-forms" tabindex="-1">Set Custom Commission Rates for Your Forms <a class="header-anchor" href="#set-custom-commission-rates-for-your-forms" aria-label="Permalink to &quot;Set Custom Commission Rates for Your Forms&quot;">​</a></h2><p>Click the <strong>Manage</strong> link to tell FluentAffiliate how much to pay for referrals from specific forms. This is where you set the commission that overrides your global rate.</p><p>Check the box for <strong>Enable custom rate for specific forms</strong>. This will reveal the configuration options.</p><ul><li><p><strong>Select Forms:</strong> Click inside the &quot;Select&quot; box and choose the payment form you want to set a commission for.</p></li><li><p><strong>Select Rate:</strong> Enter the commission amount and choose whether it&#39;s a Percentage (%) of the payment or a Fixed amount.</p></li><li><p><strong>Add More Rates:</strong> To set up commissions for another form, click the +Add New Group button. This will add a new row where you can select another form and set its rate.</p></li></ul><p><strong>Save Settings:</strong> Once you&#39;re done, click the <strong>Save Settings</strong> button.</p>',5)),t("p",null,[i(o,{src:"/guide/public/images/integrations/fluentforms/custom-rate-setup.webp",alt:"FluentForms Settings"})]),e[2]||(e[2]=n('<h2 id="creating-a-custom-affiliate-registration-form" tabindex="-1">Creating a Custom Affiliate Registration Form <a class="header-anchor" href="#creating-a-custom-affiliate-registration-form" aria-label="Permalink to &quot;Creating a Custom Affiliate Registration Form&quot;">​</a></h2><p>You can also use FluentForms to create a beautiful, custom registration form for users who want to become your affiliates.</p><h3 id="step-1-create-your-registration-form" tabindex="-1">Step 1: Create Your Registration Form <a class="header-anchor" href="#step-1-create-your-registration-form" aria-label="Permalink to &quot;Step 1: Create Your Registration Form&quot;">​</a></h3><p>In FluentForms, create a new form with all the fields you need for registration, such as:</p><ul><li><p>Name Fields</p></li><li><p>Email</p></li><li><p>Password</p></li><li><p>Payment Email</p></li><li><p>Website URL (Optional)</p></li></ul>',5)),t("p",null,[i(o,{src:"/guide/public/images/integrations/fluentforms/edit-form.webp",alt:"Configure Forms"})]),e[3]||(e[3]=n('<h3 id="step-2-configure-the-integration-feed" tabindex="-1">Step 2: Configure the Integration Feed <a class="header-anchor" href="#step-2-configure-the-integration-feed" aria-label="Permalink to &quot;Step 2: Configure the Integration Feed&quot;">​</a></h3><p>Next, you need to connect this specific form to *<strong>FluentAffiliate&#39;s</strong> registration system.</p><ol><li><p>Go into the settings for your registration form and click on <strong>Settings &amp; Integrations</strong>.</p></li><li><p>From the left menu, select <strong>Configure Integrations</strong>.</p></li><li><p>Click the <strong>Add New Integration</strong> button and choose <strong>Fluent Affiliate Registration Integration</strong> from the dropdown list.</p></li></ol>',3)),t("p",null,[i(o,{src:"/guide/public/images/integrations/fluentforms/fluentaffiliate-integrations.webp",alt:"Settings & Integrations"})]),e[4]||(e[4]=n('<h3 id="step-3-map-your-form-fields" tabindex="-1">Step 3: Map Your Form Fields <a class="header-anchor" href="#step-3-map-your-form-fields" aria-label="Permalink to &quot;Step 3: Map Your Form Fields&quot;">​</a></h3><p>Now, you need to tell FluentAffiliate which form field corresponds to which piece of affiliate data.</p><ul><li><p><strong>Integration Name:</strong> Give your feed a recognizable name.</p></li><li><p><strong>User Type:</strong> Decide what kind of account is created when the form is submitted. You can choose from two options in the dropdown menu:</p><ul><li><p><strong>Create New WordPress User + Affiliate:</strong> Select this option to allow new visitors to register as affiliates. When they submit the form, it will easily create a WordPress user account and an affiliate account for them.</p></li><li><p><strong>Create Affiliate for Existing User (must be logged in):</strong> Choose this option for existing members of your site who want to become affiliates. The user must be logged into their WordPress account to use the form. Upon submission, an affiliate profile will be created and linked to their existing user account.</p></li></ul></li><li><p><strong>Map Fields:</strong> For each Affiliate Field (like Email Address, Full Name, Password), select the corresponding field from your form in the dropdown on the right.</p></li><li><p><strong>Auto Approve Affiliate:</strong> Choose whether to use the global setting, automatically approve the affiliate, or keep their application pending for you to review manually.</p></li><li><p><strong>Conditional Logic:</strong> You can enable this to process the registration feed only when certain conditions are met. For example, you could set a condition to only register a user as an affiliate if they select a &quot;Yes, I agree to the terms&quot; checkbox on your form.</p></li><li><p><strong>Status:</strong> Ensure the Enable this Integration checkbox is checked to make the feed active. You can uncheck this at any time to temporarily disable new affiliate registrations through this form without deleting your settings.</p></li><li><p>Click <strong>Save Feed</strong> when you are done.</p></li></ul><p>After saving, a success message will appear confirming that the feed has been created.</p><p>Now, you can easily <strong>edit</strong>, <strong>delete</strong>, or <strong>disable</strong> this feed at any time from the form&#39;s integration settings.</p>',5)),t("p",null,[i(o,{src:"/guide/public/images/integrations/fluentforms/form-integration-feed.webp",alt:"Integrations Feed"})]),e[5]||(e[5]=n('<h3 id="embed-your-form" tabindex="-1">Embed your Form <a class="header-anchor" href="#embed-your-form" aria-label="Permalink to &quot;Embed your Form&quot;">​</a></h3><p>Once you complete the customizations, click the <strong>Preview &amp; Design</strong> button in the middle of the screen. This will allow you to see a live preview of how your form will look on the front end.</p><p>To display the form on a specific page or post, simply <strong>copy</strong> the <strong>Shortcode</strong> from the top right corner of the screen. Then, paste this shortcode into the content area of your desired <strong>Page</strong> or <strong>Post</strong>.</p><p>This will embed the form on your website, making it visible and ready for users to interact with.</p>',4)),t("p",null,[i(o,{src:"/guide/public/images/integrations/fluentforms/embedded-form-settings.webp",alt:"Embedded Form"})]),e[6]||(e[6]=t("h2",{id:"generate-an-affiliate-link",tabindex:"-1"},[r("Generate an Affiliate Link "),t("a",{class:"header-anchor",href:"#generate-an-affiliate-link","aria-label":'Permalink to "Generate an Affiliate Link"'},"​")],-1)),e[7]||(e[7]=t("p",null,[r("Once your form is live, your affiliates can start promoting it. To learn more about "),t("a",{href:"/guide/affiliate-portal/generating-affiliate-links"},"affiliate link"),r(", read this documentation.")],-1)),e[8]||(e[8]=t("p",null,"If someone clicks the link, you will get the affiliate commission.",-1)),t("p",null,[i(o,{src:"/guide//public/images/integrations/fluentforms/referral.webp",alt:"Referral"})]),e[9]||(e[9]=t("h3",{id:"troubleshooting-common-issues",tabindex:"-1"},[r("Troubleshooting Common Issues "),t("a",{class:"header-anchor",href:"#troubleshooting-common-issues","aria-label":'Permalink to "Troubleshooting Common Issues"'},"​")],-1)),e[10]||(e[10]=t("p",null,"Here are solutions to common issues you might encounter:",-1)),e[11]||(e[11]=t("ul",null,[t("li",null,[t("strong",null,"Registration Form Not Working:"),r(" Double-check that you have correctly mapped all the required fields (like Email and Password) in the form's integration feed. An unmapped required field will cause the registration to fail.")])],-1)),e[12]||(e[12]=t("p",null,"And that's it. This is an easy process to integrate FluentForms with FluentAffiliate.",-1))])}const F=a(u,[["render",g]]);export{w as __pageData,F as default};
